/// <summary>
/// extension of FormControl AVAButtonConfirm
/// </summary>
[ExtensionOf(formControlStr(PurchTable, AVAButtonConfirm))]
final class AVAPurchTableFrm_AVAButtonConfirm_Extension
{
}

Method.Source:
/// <summary>
/// AVA
/// </summary>
public void clicked()
{
    next clicked();

    FormRun avaPurchTableFormRun = this.FormRun();
    FormDataSource avaPurchTable_fds = avaPurchTableFormRun.dataSource(formDataSourceStr(PurchTable, PurchTable));
    str avaPurchOrders = element.avaGetDiffCategoryOrders(avaPurchTable_fds);

    if(avaPurchOrders == ''
        || (avaPurchOrders != ''
            && element.avaConfirmPurchTablesDialog(avaPurchOrders) == DialogButton::Yes))
    {
        element.avaButtonConfirmClicked();
    }
}
